// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address admin) public {
        // Rule (universal): delegating c.initialize into any fresh storage context must COMPLETE
        // successfully for every admin, because the initializer machinery sets the initializing
        // flag before the onlyInitializing child initializers run.
        // The mutant drops the initializer modifier, so its child initializers revert
        // (NotInitializing) and the boundary call fails for every input.
        vm.assume(admin != address(0));

        (bool ok, ) = address(c).delegatecall(
            abi.encodeWithSignature("initialize(address)", admin)
        );

        assertTrue(ok);
    }
}
